        <h2>创建角色成功，故事开始喽♡</h2>
    </div>

    <script>
        const paimonText = document.getElementById('paimon-text');
        const nameInput = document.getElementById('name');

        // ✨ 新增：SillyTavern交互函数
        const triggerQuickReply = (text) => {
            if (typeof triggerSlash === 'function') {
                const command = `/send ${text}|/trigger`;
                triggerSlash(command);
            } else {
                // 如果不在SillyTavern环境中，则在控制台打印信息，方便调试
                console.log(`SillyTavern环境未检测到。本应执行命令: /send ${text}|/trigger`);
                alert(`模拟发送信息:\n${text}`);
            }
        };

        // ✨ 新增：格式化角色信息函数
        const formatCharacterInfo = (gender, name, element) => {
            const genderIcon = gender === '哥哥' ? '♂️' : '♀️';
            const elementIcons = { Anemo: '🌪️', Geo: '⛰️', Electro: '⚡', Dendro: '🌿', Hydro: '💧', Pyro: '🔥', Cryo: '❄️' };
            const elementIcon = elementIcons[element] || '❔';

            return `
╔═══════  角色信息  ══════╗
║                                  
║   样貌: ${gender} ${genderIcon}                  
║   名字: ${name}                   
║   元素: ${element} ${elementIcon}               
║                                  
╚══════════════════╝
            `.trim();
        };


        function selectGender(gender) {
            document.getElementById('gender-input').value = gender;
            document.querySelectorAll('.gender-option').forEach(el => el.classList.remove('selected'));
            document.getElementById(`${gender}-option`).classList.add('selected');
            nameInput.placeholder = (gender === 'male') ? '空' : '荧';
            paimonText.textContent = (gender === 'male') ? "决定是哥哥啦！看起来就很可靠的样子嘛！" : "是可爱的妹妹呀！未来的冒险一定会很有趣！";
        }

        document.querySelectorAll('.element-option').forEach(option => {
            option.addEventListener('click', () => {
                const selectedElement = option.dataset.element;
                document.getElementById('element-input').value = selectedElement;
                document.querySelectorAll('.element-option').forEach(el => el.classList.remove('selected'));
                option.classList.add('selected');
                const elementPaimonLines = { Anemo: "是自由的风！感觉随时都能飞起来！", Geo: "岩的力量，稳重又坚定，就像大地一样值得信赖！", Electro: "噼里啪啦的雷元素！是不是有点急性子呀？", Dendro: "草元素的智慧，和派蒙一样，充满了生命的奥秘！嘿嘿。", Hydro: "纯净的水，能包容一切，也能击穿岩石！", Pyro: "火！热情似火！以后我们的烤肉就靠你啦！", Cryo: "冰冷冷的，但说不定内心很火热呢！" };
                paimonText.textContent = elementPaimonLines[selectedElement] || "哇，这是什么力量？好神奇！";
            });
        });

        nameInput.addEventListener('focus', () => {
            paimonText.textContent = "嗯，一个好名字是伟大冒险的开始！让派蒙看看你想叫什么？";
        });

        document.getElementById('submit-btn').addEventListener('click', function() {
            const name = nameInput.value || nameInput.placeholder;
            const element = document.getElementById('element-input').value;
            if (!element) { paimonText.textContent = "别忘了选择一个与你共鸣的元素哦！"; return; }
            const gender = document.getElementById('gender-input').value === 'male' ? '哥哥' : '妹妹';
            document.getElementById('confirm-gender').textContent = gender;
            document.getElementById('confirm-name').textContent = name;
            const elementSpan = document.getElementById('confirm-element');
            elementSpan.innerHTML = `<div class="element-icon-small" style="background-image: var(--element-${element.toLowerCase()});"></div> ${element}`;
            document.getElementById('confirmation-modal').style.display = 'flex';
        });

        document.getElementById('edit-btn').addEventListener('click', () => {
            document.getElementById('confirmation-modal').style.display = 'none';
        });

        document.getElementById('confirm-btn').addEventListener('click', () => {
            const creationContainer = document.getElementById('creation-container');
            const confirmationModal = document.getElementById('confirmation-modal');
            const loadingScreen = document.getElementById('loading-screen');
            const finalScreen = document.getElementById('final-screen');

            // ✨ 修改：在执行动画前，发送角色信息
            const gender = document.getElementById('confirm-gender').textContent;
            const name = document.getElementById('confirm-name').textContent;
            const element = document.getElementById('element-input').value; // 从隐藏输入框获取原始元素名称
            const formattedInfo = formatCharacterInfo(gender, name, element);
            triggerQuickReply(formattedInfo);


            // Fade out modals and container
            creationContainer.style.transition = 'opacity 0.5s ease-out';
            creationContainer.style.opacity = '0';
            confirmationModal.style.transition = 'opacity 0.5s ease-out';
            confirmationModal.style.opacity = '0';

            setTimeout(() => {
                creationContainer.style.display = 'none';
                confirmationModal.style.display = 'none';

                // Show loading screen
                loadingScreen.classList.add('visible');

                setTimeout(() => {
                    loadingScreen.classList.remove('visible');
                    // Show final screen
                    finalScreen.classList.add('visible');
                }, 3000); // 缩短加载时间以便快速看到效果

            }, 500); // Wait for fade out to complete
        });
    </script>
</body>
</html>
