<script>
document.addEventListener('DOMContentLoaded', () => {
    // --- Radar Chart Logic ---
    const radarCanvas = document.getElementById('radar-chart');
    if (radarCanvas) {
        const radarCtx = radarCanvas.getContext('2d');
        const radarData = {
            labels: ['攻击', '防御', '速度', '暴击', '爆伤', '颜值'],
            values: [
                parseInt('$20') || 0, parseInt('$21') || 0, parseInt('$22') || 0,
                parseInt('$23') || 0, parseInt('$24') || 0, parseInt('$25') || 0
            ]
        };

        function drawRadarChart(ctx, data, maxValue = 100) {
            const { labels, values } = data;
            const numAxes = labels.length;
            const width = ctx.canvas.width;
            const height = ctx.canvas.height;
            const centerX = width / 2;
            const centerY = height / 2;
            const radius = Math.min(centerX, centerY) * 0.7;

            ctx.strokeStyle = 'rgba(0, 0, 0, 0.1)'; ctx.lineWidth = 1;
            for (let i = 1; i <= 4; i++) {
                ctx.beginPath(); const r = radius * (i / 4);
                for (let j = 0; j < numAxes; j++) {
                    const angle = (Math.PI * 2 * j) / numAxes - Math.PI / 2;
                    const x = centerX + r * Math.cos(angle); const y = centerY + r * Math.sin(angle);
                    j === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
                }
                ctx.closePath(); ctx.stroke();
            }

            ctx.strokeStyle = 'rgba(0, 0, 0, 0.1)';
            for (let i = 0; i < numAxes; i++) {
                const angle = (Math.PI * 2 * i) / numAxes - Math.PI / 2;
                ctx.beginPath(); ctx.moveTo(centerX, centerY); ctx.lineTo(centerX + radius * Math.cos(angle), centerY + radius * Math.sin(angle)); ctx.stroke();
            }

            ctx.fillStyle = '#4B5563'; ctx.font = '12px sans-serif';
            for (let i = 0; i < numAxes; i++) {
                const angle = (Math.PI * 2 * i) / numAxes - Math.PI / 2;
                const x = centerX + (radius + 15) * Math.cos(angle); const y = centerY + (radius + 15) * Math.sin(angle);
                ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(labels[i], x, y);
            }

            ctx.beginPath();
            for (let i = 0; i < numAxes; i++) {
                const value = Math.min(values[i], maxValue); const r = radius * (value / maxValue);
                const angle = (Math.PI * 2 * i) / numAxes - Math.PI / 2;
                const x = centerX + r * Math.cos(angle); const y = centerY + r * Math.sin(angle);
                i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
            }
            ctx.closePath(); ctx.strokeStyle = 'rgba(99, 102, 241, 0.8)'; ctx.fillStyle = 'rgba(139, 92, 246, 0.3)'; ctx.lineWidth = 2; ctx.stroke(); ctx.fill();
        }

        const radarSection = document.getElementById('radar-section');
        radarCanvas.width = radarSection.clientWidth; radarCanvas.height = radarSection.clientWidth * 0.9;
        drawRadarChart(radarCtx, radarData);
    }

    // --- Modal Logic ---
    const modal = document.getElementById('radar-modal');
    const openBtn = document.getElementById('radar-section');
    const closeBtn = document.getElementById('modal-close-btn');
    if(openBtn) openBtn.onclick = () => { if(modal) modal.style.display = 'flex'; };
    if(closeBtn) closeBtn.onclick = () => { if(modal) modal.style.display = 'none'; };
    window.onclick = (event) => { if (event.target == modal) { modal.style.display = 'none'; } };

    // --- **FIXED** Collapsible Logic ---
    const handleCollapse = (summaryElement) => {
        const detail = summaryElement.nextElementSibling;
        const parentContent = summaryElement.closest('.collapsible-content');
        if (!detail) return;

        const isOpening = detail.style.maxHeight !== `${detail.scrollHeight}px`;

        // Close all other details in the same list
        const listContainer = summaryElement.closest('.collapsible-content');
        if (listContainer) {
            listContainer.querySelectorAll('.item-detail, .partner-detail, .skill-detail, .quest-detail').forEach(d => {
                if (d !== detail) {
                    d.style.maxHeight = null;
                }
            });
        }

        // Open or close the clicked detail
        detail.style.maxHeight = isOpening ? `${detail.scrollHeight}px` : null;

        // Adjust parent container height after animation
        if (parentContent && parentContent.style.maxHeight) {
            setTimeout(() => {
                parentContent.style.maxHeight = `${parentContent.scrollHeight}px`;
            }, 400); // Should match the transition duration
        }
    };

    document.querySelectorAll('.collapsible-header').forEach(header => {
        header.addEventListener('click', () => {
            header.classList.toggle('open');
            const content = header.nextElementSibling;
            if (content.style.maxHeight) {
                content.style.maxHeight = null;
                content.classList.remove('open');
            } else {
                content.style.maxHeight = content.scrollHeight + "px";
                content.classList.add('open');
            }
        });
    });

    // --- Data Injection Logic ---
    const injectData = (containerId, dataString, templateFn) => {
        try {
            const container = document.getElementById(containerId);
            if (!container || !dataString || dataString.trim() === '' || dataString.startsWith('$')) return;
            const data = JSON.parse(dataString.trim());
            data.forEach(item => {
                const listItem = document.createElement('div');
                listItem.className = 'list-item';
                listItem.innerHTML = templateFn(item);
                container.appendChild(listItem);
                const summary = listItem.querySelector('.item-summary, .partner-summary, .skill-summary, .quest-summary');
                if (summary) summary.addEventListener('click', () => handleCollapse(summary));
            });
        } catch (e) { console.error(`Error injecting data for ${containerId}:`, e); }
    };

    injectData('item-list-container', `$15`, item => `
        <div class="item-summary"><div class="item-icon">${item.icon || '📦'}</div><div class="item-info"><div class="item-name">${item.name}</div><div class="item-quantity">数量: ${item.quantity}</div></div></div>
        <div class="item-detail"><div class="item-detail-content"><div class="detail-grid">
            <span class="label">来源:</span><span class="value">${item.source || '未知'}</span>
            <span class="label">作用:</span><span class="value">${item.effect || '无'}</span>
            <span class="label value full-width">简介:</span><span class="value full-width">${item.desc || '...'}</span>
        </div></div></div>
    `);
    injectData('partner-list-container', `$16`, partner => `
        <div class="partner-summary"><div class="partner-avatar" style="background-image: url('${partner.avatar}');"></div><div class="partner-info"><div class="partner-name">${partner.name}</div><div class="partner-status">${partner.identity}</div></div></div>
        <div class="partner-detail"><div class="partner-detail-content"><div class="detail-grid">
            <span class="label">性别:</span><span class="value">${partner.gender}</span><span class="label">等级:</span><span class="value">${partner.level}</span>
            <span class="label">元素:</span><span class="value">${partner.vision}</span><span class="label">国家:</span><span class="value">${partner.nation}</span>
            <span class="label">好感度:</span><span class="value">${partner.favorability} (${partner.favorability_rank})</span><span class="label">淫乱度:</span><span class="value">${partner.lewdness} (${partner.lewdness_rank})</span>
        </div></div></div>
    `);
    injectData('skill-list-container', `$17`, skill => `
        <div class="skill-summary"><div class="skill-icon">${skill.icon || '✨'}</div><div class="skill-info"><div class="skill-name">${skill.name}</div><div class="skill-type">${skill.type}</div></div></div>
        <div class="skill-detail"><div class="skill-detail-content"><div class="detail-grid">
            <span class="label">${skill.type === '元素爆发' ? '能量消耗' : '冷却'}:</span><span class="value">${skill.cost || skill.cooldown || '无'}</span>
            <span class="label value full-width">描述:</span><span class="value full-width">${skill.desc || '...'}</span>
        </div></div></div>
    `);
    injectData('quest-list-container', `$18`, quest => `
        <div class="quest-summary"><div class="quest-icon">${quest.icon || '🗺️'}</div><div class="quest-info"><div class="quest-name">${quest.name}</div><div class="quest-status">状态: ${quest.status}</div></div></div>
        <div class="quest-detail"><div class="quest-detail-content"><div class="detail-grid">
            <span class="label">目标:</span><span class="value">${quest.objective || '...'}</span><span class="label">报酬:</span><span class="value">${quest.reward || '未知'}</span>
        </div></div></div>
    `);

    // --- Action Buttons ---
    const actionListContainer = document.getElementById('action-list-container');
    try {
        const optionsData = `$19`;
        if (optionsData && optionsData.trim() !== '' && !optionsData.startsWith('$')) {
            const options = JSON.parse(optionsData.trim());
            options.forEach(optionText => {
                const li = document.createElement('li');
                li.className = 'action-button';
                li.textContent = optionText;
                li.addEventListener('click', () => {
                    if (typeof triggerSlash === 'function' && optionText.trim() !== '（什么也不做）') {
                        triggerSlash(`/send ${optionText.replace(/"/g, '')}|/trigger`);
                    }
                });
                actionListContainer.appendChild(li);
            });
        }
    } catch (e) { console.error('Error creating action buttons:', e); }
});
</script>
</body>
