    <script>
        document.addEventListener('DOMContentLoaded', async () => {
            let currencies = { primogems: 0, intertwined_fates: 0, acquaint_fates: 0 };
            const lorebookName = "原神1";
            const entryComment = "资源";
            let resourceEntryUid = null;

            const currencyItems = document.querySelectorAll('.currency-item');
            const modal = document.getElementById('info-modal');
            const modalTitle = document.getElementById('modal-title');
            const modalDescription = document.getElementById('modal-description');

            // --- SillyTavern API 函数 ---
            const getResourceEntry = async () => {
                if (typeof getLorebookEntries !== 'function') {
                    console.warn("SillyTavern API 'getLorebookEntries' is not available.");
                    return null;
                }
                try {
                    const entries = await getLorebookEntries(lorebookName, { filter: { comment: entryComment }, fields: ['uid', 'content'] });
                    if (entries && entries.length > 0) {
                        resourceEntryUid = entries[0].uid;
                        return entries[0];
                    }
                } catch (e) { console.error(`Error finding entry in '${lorebookName}':`, e); }
                return null;
            };

            // --- 新增：从聊天记录同步数据 ---
            const syncDataFromChatHistory = async () => {
                if (typeof getChatMessages !== 'function') {
                    console.warn("SillyTavern API 'getChatMessages' is not available.");
                    return false; // 表示同步失败
                }

                try {
                    // 获取最近的20条消息进行检查
                    const lastMessageId = await getLastMessageId();
                    const messages = await getChatMessages(`0-${lastMessageId}`);
                    const regex = /■({.*?"primogems".*?})■/;

                    // 从后往前遍历消息
                    for (let i = messages.length - 1; i >= 0; i--) {
                        const msg = messages[i].message;
                        const match = msg.match(regex);

                        if (match && match[1]) {
                            console.log(`Found data in message ${messages[i].message_id}:`, match[1]);
                            try {
                                const data = JSON.parse(match[1]);
                                // 验证数据结构
                                if ('primogems' in data && 'intertwined_fates' in data && 'acquaint_fates' in data) {
                                    currencies = { ...currencies, ...data };
                                    console.log("Successfully synced currencies from chat history.", currencies);
                                    // 找到并解析成功后，立即更新世界书
                                    await updateLorebookData();
                                    return true; // 表示同步成功
                                }
                            } catch (e) {
                                console.warn(`Failed to parse JSON from message ${messages[i].message_id}. Content: ${match[1]}`, e);
                                // 解析失败，继续往前找
                            }
                        }
                    }
                } catch (e) {
                    console.error("Error during chat history sync:", e);
                }

                console.log("No valid resource data found in recent chat history.");
                return false; // 表示未找到或同步失败
            };


            const updateLorebookData = async () => {
                // 确保 resourceEntryUid 存在，如果不存在则先获取
                if (resourceEntryUid === null) {
                    await getResourceEntry();
                }

                if (typeof setLorebookEntries !== 'function' || resourceEntryUid === null) {
                    console.warn("SillyTavern API 'setLorebookEntries' is not available or resource UID is unknown.");
                    return;
                }
                try {
                    const content = JSON.stringify(currencies);
                    await setLorebookEntries(lorebookName, [{ uid: resourceEntryUid, content: content }]);
                    console.log("Lorebook updated successfully with:", content);
                } catch (e) { console.error("Error updating lorebook:", e); }
            };

            // --- UI 函数 ---
            const updateCurrencyDisplay = () => {
                document.getElementById('primogem-count').textContent = currencies.primogems || 0;
                document.getElementById('intertwined-count').textContent = currencies.intertwined_fates || 0;
                document.getElementById('acquaint-count').textContent = currencies.acquaint_fates || 0;
                updateButtonStates();
            };

            const updateButtonStates = () => {
                document.getElementById('pull-char-button').disabled = currencies.intertwined_fates < 1;
                document.getElementById('pull-weapon-button').disabled = currencies.acquaint_fates < 1;
                document.getElementById('exchange-intertwined').disabled = currencies.primogems < 160;
                document.getElementById('exchange-acquaint').disabled = currencies.primogems < 160;
            };

            const showScreen = (screenId) => {
                document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
                document.getElementById(screenId).classList.add('active');
                document.querySelector('.back-button').style.display = (screenId === 'main-screen') ? 'none' : 'flex';
            };

            // 修改了 sendResultToChat，使其使用更可靠的标记 ■
            const sendResultToChat = (message) => {
                const remainingData = `<!--${JSON.stringify(currencies)}-->`;
                const fullMessage = `${message}\n${remainingData}`;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/send ${fullMessage}|/trigger`);
                } else {
                    console.log(`Would trigger: /send ${fullMessage}|/trigger`);
                    alert(fullMessage);
                }
            };

            const playGachaAnimation = (rarity, type) => {
                const gifPlayer = document.getElementById('gif-player');
                const gifResultImg = document.getElementById('gif-result');
                const gifUrls = {
                    '3': 'https://i.postimg.cc/02GtxKhv/Screenshot-2025-1103-004019.gif',
                    '4': 'https://i.postimg.cc/02d0wRkb/Screenshot-2025-1103-004120.gif',
                    '5': 'https://i.postimg.cc/bN8Q8CQ3/Screenshot-2025-1103-004150.gif'
                };
                const gifUrl = gifUrls[rarity];
                const img = new Image();
                img.src = gifUrl;
                img.onload = () => {
                    gifResultImg.src = gifUrl;
                    gifPlayer.style.display = 'flex';
                    setTimeout(() => {
                        gifPlayer.style.display = 'none';
                        gifResultImg.src = '';
                        const typeText = type === 'character' ? '角色' : '武器';
                        sendResultToChat(`恭喜抽取到${rarity}星${typeText}，请等待回复后揭晓结果`);
                    }, 7000);
                };
            };

            // --- 核心逻辑 ---
            const handleGacha = async (type) => {
                if (type === 'character' && currencies.intertwined_fates > 0) {
                    currencies.intertwined_fates--;
                } else if (type === 'weapon' && currencies.acquaint_fates > 0) {
                    currencies.acquaint_fates--;
                } else { return; }

                updateCurrencyDisplay();
                await updateLorebookData();

                const rand = Math.random() * 100;
                const rarity = rand < 80 ? 3 : (rand < 95 ? 4 : 5);
                playGachaAnimation(rarity, type);
            };

            const handleExchange = async (type) => {
                if (currencies.primogems < 160) return;
                currencies.primogems -= 160;
                if (type === 'intertwined') {
                    currencies.intertwined_fates++;
                } else {
                    currencies.acquaint_fates++;
                }

                updateCurrencyDisplay();
                await updateLorebookData();
            };

            // --- 事件绑定 ---
            document.getElementById('to-char-pool').addEventListener('click', () => showScreen('char-pool-screen'));
            document.getElementById('to-weapon-pool').addEventListener('click', () => showScreen('weapon-pool-screen'));
            document.querySelector('.back-button').addEventListener('click', (e) => showScreen(e.currentTarget.dataset.target));
            document.getElementById('pull-char-button').addEventListener('click', () => handleGacha('character'));
            document.getElementById('pull-weapon-button').addEventListener('click', () => handleGacha('weapon'));
            document.getElementById('exchange-intertwined').addEventListener('click', () => handleExchange('intertwined'));
            document.getElementById('exchange-acquaint').addEventListener('click', () => handleExchange('acquaint'));

            currencyItems.forEach(item => {
                item.addEventListener('click', (e) => {
                    e.stopPropagation();
                    modalTitle.textContent = item.dataset.title;
                    modalDescription.innerHTML = item.dataset.description;
                    modal.classList.add('visible');
                });
            });
            modal.addEventListener('click', () => modal.classList.remove('visible'));

            // --- 初始化 ---
            // 1. 优先尝试从聊天记录同步数据
            const syncedFromChat = await syncDataFromChatHistory();

            // 2. 如果聊天记录同步失败，则回退到从世界书加载
            if (!syncedFromChat) {
                const entry = await getResourceEntry();
                if (entry) {
                    try {
                        const data = JSON.parse(entry.content);
                        currencies = { ...currencies, ...data };
                    } catch {
                        console.error("Failed to parse lorebook content. Using default values.");
                    }
                } else {
                     console.warn(`Entry '${entryComment}' not found in lorebook '${lorebookName}'. Using default values.`);
                }
            }

            // 3. 更新UI显示
            updateCurrencyDisplay();
        });
    </script>
</body>
</html>
