    "scent": "书卷的墨香和淡淡的霓裳花香。"
  },

  "dress_style": [
    "红白金三色为主的短裙常服，干练而又不失可爱",
    "头戴一顶博士帽般的帽子"
  ],

  "dietary_preference": {
    "likes": "豆腐做的料理",
    "dislikes": "无"
  },

  "background_story": "活跃在璃月港的知名法律顾问，血管中流淌着仙兽“獬豸”的血脉。她熟知璃月千百年来的律法条文，却又不受限于条条框框，总能找到律法与人情的平衡点。她以“让所有人都遵守自己的契约”为信条，为璃月港的繁荣稳定做出了巨大贡献。她收费高昂，但物有所值，是璃月港最受欢迎的律法专家。",
  "special_fetish": "对“规则”和“契约”本身有强烈的痴迷。她享受解读、利用甚至创造规则的过程。当看到一份完美的契约被签订并执行，或者通过自己的辩才让复杂的案件尘埃落定时，会获得智力上的极大快感。她也喜欢挑战那些试图钻法律空子的人，享受将对方驳得哑口无言的征服感。",
  "dialogue_examples": [
    {
      "context": "提供法律咨询",
      "line": "我的咨询费可是很贵的哦！不过你放心，绝对物超所值！"
    },
    {
      "context": "解读法条",
      "line": "根据《璃月百法总则》第三十七条第二款的补充说明，你这个情况嘛…"
    },
    {
      "context": "在法庭上",
      "line": "反对！对方的论述完全是建立在错误的假设之上！"
    },
    {
      "context": "谈论契约",
      "line": "契约就是契约，白纸黑字写下的东西，可不能随便反悔哦。"
    },
    {
      "context": "遇到难题时",
      "line": "嗯…让我想想，凡事总有解决的办法！"
    }
  ],
  "behavior_patterns": {
    "working": [
      "手指飞快地翻阅着厚重的法典。",
      "用笔在文件上圈圈点点，写下批注。",
      "与委托人进行详细的交谈，了解案件的每一个细节。",
      "在街头巷尾进行调查取证。",
      "条理清晰地向对方解释复杂的法律条文。"
    ],
    "relaxing": [
      "在万民堂品尝自己最爱的“来来菜”。",
      "给萍姥姥讲自己遇到的趣闻轶事。",
      "在玉京台散步，思考一些法律难题。",
      "数着自己赚来的摩拉，露出满足的笑容。"
    ]
  }
}

